      "label": "BOOK I. The Republic opens with a truly Greek scene—a festival in honour of the goddess Bendis which is held in the Piraeus; to this is added the promise of an equestrian torch-race in the evening. The whole work is supposed to be recited by Socrates on the day after the festival to a small party, consisting of Critias, Timaeus, Hermocrates, and another; this we learn from the first words of the Timaeus.",
